var state=loadState();
var reportSort={key:'line',dir:1};
var cashSelectedMonths=null;
var penSelected=new Set(), penDetailKey='';

function defaultPenBlocks(){return [{id:'01',name:'Bloco 01',lines:['A','B','C','D','E','F']},{id:'02',name:'Bloco 02',lines:['G','H','I','J','K']},{id:'03',name:'Bloco 03',lines:['L','M','N','O','P']}];}
function normalizedPenBlocks(saved){var standard=defaultPenBlocks();if(!Array.isArray(saved)||saved.length!==3)return standard;return standard.map(function(block,i){return {id:block.id,name:String((saved[i]||{}).name||block.name),lines:block.lines.slice()};});}
function defaults(){return {version:1,year:2027,horizonMonths:12,capacity:CAPACITY,capacityByMonth:{},penBlocks:defaultPenBlocks(),defaults:{sale:1500,buy:1100,hotel:350},cash:{paymentDays:0,anticipate:false,annualInterest:6.5},lots:[],notes:[],shipmentPlans:[],hasConsumo:true,plans:[],activePlanId:null,updatedAt:new Date().toISOString()};}
function loadState(){try{var d=JSON.parse(localStorage.getItem(KEY));if(d&&Array.isArray(d.lots)){var base=defaults();return Object.assign(base,d,{horizonMonths:Number(d.horizonMonths)===24?24:12,capacity:num(d.capacity)||CAPACITY,capacityByMonth:d.capacityByMonth||{},penBlocks:normalizedPenBlocks(d.penBlocks),defaults:Object.assign(base.defaults,d.defaults||{}),cash:Object.assign(base.cash,d.cash||{}),notes:Array.isArray(d.notes)?d.notes:[],shipmentPlans:Array.isArray(d.shipmentPlans)?d.shipmentPlans:[],hasConsumo:d.hasConsumo!==false});}}catch(e){}return defaults();}
function save(){state.updatedAt=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(state));}
function el(id){return document.getElementById(id);}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function num(v){v=Number(v);return isFinite(v)?v:0;}
function int(v){return Math.round(num(v)).toLocaleString('pt-BR');}
function usd(v){return 'US$ '+Math.round(num(v)).toLocaleString('pt-BR');}
function uid(prefix){return (prefix||'id')+'_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7);}
function keyOf(y,m){return String(y)+'-'+String(m+1).padStart(2,'0');}
function addMonths(key,n){var p=String(key).split('-'),d=new Date(Number(p[0]),Number(p[1])-1+n,1);return keyOf(d.getFullYear(),d.getMonth());}
function labelKey(key){if(!key)return '—';var p=key.split('-');return MONTHS[Number(p[1])-1]+'/'+p[0].slice(2);}
function planningStartKey(){var d=new Date();return keyOf(d.getFullYear(),d.getMonth());}
function horizonMonths(){return Number(state.horizonMonths)===24?24:12;}
function monthKeys(){var start=planningStartKey();return Array.from({length:horizonMonths()},function(_,i){return addMonths(start,i);});}
function updateHorizonLabels(){var months=horizonMonths(),start=planningStartKey();el('planningWindow').textContent=labelKey(start)+' a '+labelKey(addMonths(start,months-1));el('horizonMonths').value=String(months);el('capacityHorizonTitle').textContent='Capacidade nos próximos '+months+' meses';['overviewRange','cashRange','capacityRange'].forEach(function(id){var select=el(id),current=Number(select.value)||4;Array.from(select.querySelectorAll('[data-long-range]')).forEach(function(o){o.remove();});if(months===24){[18,24].forEach(function(value){var option=document.createElement('option');option.value=String(value);option.textContent=value+' meses';option.dataset.longRange='1';select.appendChild(option);});}if(current>months)current=months;select.value=String(current);});}
function capacityFor(key){return Math.max(1,Math.round(num((state.capacityByMonth||{})[key])||num(state.capacity)||CAPACITY));}
function sum(a,fn){return a.reduce(function(s,x,i){return s+(fn?num(fn(x,i)):num(x));},0);}
function showToast(msg){var t=el('toast');t.textContent=msg;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(function(){t.classList.remove('show');},2600);}
function lotTypeLabel(t){return t==='rural'?'Rural':t==='toreton'?'Toreton':'Hotelaria';}
function normalizedCategory(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toUpperCase();}
function categoryIsOwn(value){var category=normalizedCategory(value);return category==='RIP'||category==='TORETON'||category==='COMPRAS';}
function entryTypeIsOwn(value){return /^ANIMAIS?\b/i.test(normalizedCategory(value));}
function activeReportDate(){var lots=state.lots.filter(function(l){return l.source==='feedmanager';});return lots.length?lots.map(function(l){return l.reportDate||'';}).sort().pop():'';}
function decimal(v,d){return Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});}
function numberBR(v){var x=parseFloat(String(v||'').replace(/\./g,'').replace(',','.').replace(/[^0-9.-]/g,''));return isFinite(x)?x:0;}
function inputNumber(v){var s=String(v==null?'':v).trim();if(!s)return null;s=s.replace(/\s/g,'');if(s.indexOf(',')>=0)s=s.replace(/\./g,'').replace(',','.');var x=parseFloat(s.replace(/[^0-9.-]/g,''));return isFinite(x)?x:null;}
function lotKey(l){return normalizedCategory(l.name)+'|'+String(l.entryDate||'');}
function shipmentFor(l){var key=lotKey(l);return (state.shipmentPlans||[]).find(function(p){return p.lotKey===key;})||null;}
function deleteShipment(key){var before=(state.shipmentPlans||[]).length;state.shipmentPlans=(state.shipmentPlans||[]).filter(function(p){return p.lotKey!==key;});if(state.shipmentPlans.length===before)return;save();renderAll();if(!el('penDrawer').hidden)renderPenDetail();showToast('Embarque excluído. O lote foi mantido.');}
function parseShipmentDate(v){var s=String(v||'').trim(),m=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);if(m)return m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);return m?m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0'):'';}
function activeNotes(l){var lk=lotKey(l);return state.notes.filter(function(n){return n.status==='active'&&((n.scope==='lot'&&n.targetKey===lk)||(n.scope==='pen'&&n.targetKey===l.pen));});}
function addNote(e){e.preventDefault();var l=penDetailLot(),fd=new FormData(e.target),scope=fd.get('scope'),text=String(fd.get('text')||'').trim();if(!l||!text)return;state.notes.push({id:uid(),scope:scope,targetKey:scope==='lot'?lotKey(l):l.pen,lotName:l.name,pen:l.pen,text:text,status:'active',createdAt:new Date().toISOString(),closedAt:''});save();renderPens();renderPenDetail();showToast('Anotação salva.');}
function concludeNote(id){var n=state.notes.find(function(x){return x.id===id;});if(!n)return;n.status='closed';n.closedAt=new Date().toISOString();save();renderPens();renderPenDetail();showToast('Anotação concluída e mantida no histórico.');}
function closePenNotes(){var l=penDetailLot();if(!l)return;var list=state.notes.filter(function(n){return n.status==='active'&&n.scope==='pen'&&n.targetKey===l.pen;});if(!list.length){showToast('Este curral não possui anotação ativa.');return;}if(!confirm('Concluir as '+list.length+' anotações ativas deste curral? Elas continuarão no histórico.'))return;list.forEach(function(n){n.status='closed';n.closedAt=new Date().toISOString();});save();renderPens();renderPenDetail();showToast('Anotações do curral concluídas.');}
function noteCard(n){return '<article class="note-card '+(n.status==='closed'?'closed':'')+'">'+(n.status==='active'?'<button type="button" data-close-note="'+n.id+'">Concluir</button>':'')+'<small>'+(n.scope==='lot'?'LOTE':'CURRAL')+' · '+new Date(n.createdAt).toLocaleString('pt-BR')+(n.closedAt?' · concluída '+new Date(n.closedAt).toLocaleString('pt-BR'):'')+'</small><p>'+esc(n.text)+'</p></article>';}
function nearbyDiet(clean,y,isNew){var lo=isNew?338:340,hi=isNew?400:412;return clean.filter(function(i){var x=i.transform[4],dy=i.transform[5]-y,t=String(i.str||'').trim();return x>=lo&&x<hi&&dy>=-13&&dy<=13&&t&&!/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(t);}).sort(function(a,b){var dd=b.transform[5]-a.transform[5];return Math.abs(dd)>2?dd:a.transform[4]-b.transform[4];}).map(function(i){return String(i.str).trim();}).join(' ').trim();}
function reportColumns(hasConsumo){
  // A Bovino.OS mudou o relatório em set/2026: a coluna "Consumo MN total da baia" foi retirada,
  // o que deslocou (para a direita) todas as colunas seguintes (D. conf., D. trato, GMD, pesos, datas).
  return hasConsumo?{entryWeight:[412,441],entryDate:[443,486],days:[486,512],treatmentDays:[512,544],gmd:[544,572],estimatedWeight:[572,604],exitWeight:[604,631],estimatedExit:[632,680],consumption:[680,715],kgCabMS:[715,748],kgCabMN:[748,778],pv:[778,820]}
  :{entryWeight:[400,454],entryDate:[454,493],days:[493,535],treatmentDays:[535,565],gmd:[565,593],estimatedWeight:[593,623],exitWeight:[623,653],estimatedExit:[653,692],consumption:null,kgCabMS:[692,735],kgCabMN:[735,767],pv:[767,830]};
}
function daysSince(iso){if(!iso)return null;var d=new Date(iso+'T00:00:00'),now=new Date();now.setHours(0,0,0,0);return Math.round((now-d)/86400000);}
function freshnessLabel(iso){var n=daysSince(iso);if(n===null)return '';var cls=n>=3?'stale':n>=1?'aging':'',text=n<=0?'hoje':n===1?'há 1 dia':'há '+n+' dias';return ' <b class="freshness '+cls+'">('+text+')</b>';}
function renderHeaderPosition(){var el2=el('positionLabel');if(!el2)return;var reportDate=activeReportDate();el2.innerHTML=reportDate?'Posição em '+esc(formatIsoDate(reportDate))+freshnessLabel(reportDate):'Nenhum relatório de lotes ativos importado';}

function ruralExitFromMonthKey(mk){var entryDate=mk+'-15',exitDate=addDaysToIso(entryDate,120);return {entryDate:entryDate,exitDate:exitDate,exit:exitDate.slice(0,7)};}
function normalizeFeedManagerLots(){
  var changed=false,next=[];
  state.lots.forEach(function(l){
    if(l.source==='planejamento'){var ex=ruralExitFromMonthKey(l.entry);if(l.exit!==ex.exit||l.entryDate!==ex.entryDate){l.exit=ex.exit;l.entryDate=ex.entryDate;l.exitDate=ex.exitDate;changed=true;}next.push(l);return;}
    if(l.source!=='feedmanager'){next.push(l);return;}
    if(l.entryDate){var calculatedExit=addDaysToIso(l.entryDate,120);if(calculatedExit&&l.exitDate!==calculatedExit){l.exitDate=calculatedExit;l.exit=calculatedExit.slice(0,7);changed=true;}}
    var rawType=normalizedCategory(l.rawEntryType),hasStandardType=/^(ANIMAIS?\b|BOITEL|PARCERIA)/.test(rawType),own=hasStandardType?entryTypeIsOwn(rawType):categoryIsOwn(l.rawCategory),newType=own?'rural':'hotel',newOrigin=own?'Animal próprio':'Boitel',newEntryType=own?'Próprio':'Boitel';
    if(l.type!==newType||l.origin!==newOrigin||l.entryType!==newEntryType)changed=true;l.type=newType;l.origin=newOrigin;l.entryType=newEntryType;next.push(l);
  });
  if(next.length!==state.lots.length)changed=true;state.lots=next;if(changed)save();
}

