function updateDefaults(){
  state.defaults.sale=num(el('defaultSale').value);
  state.defaults.buy=num(el('defaultBuy').value);
  state.defaults.hotel=num(el('defaultHotel').value);

  // Estes campos são as premissas financeiras do planejamento atual. Além de
  // servirem para novos lotes, precisam atualizar os lotes já carregados para
  // que o fluxo de caixa seja recalculado imediatamente com os novos valores.
  state.lots.forEach(function(l){
    if(l.type==='rural')l.salePrice=state.defaults.sale;
    if(l.type==='toreton'){
      l.buyPrice=state.defaults.buy;
      l.salePrice=state.defaults.sale;
    }
    if(l.type==='hotel')l.hotelPrice=state.defaults.hotel;
  });

  save();
  renderForms();
  renderAll();
  showToast('Valores financeiros aplicados a todos os lotes do planejamento atual.');
}
function updateCashSettings(){state.cash=state.cash||defaults().cash;state.cash.paymentDays=Math.max(0,Math.round(num(el('cashPaymentDays').value)));state.cash.anticipate=el('cashAnticipate').value==='true';state.cash.annualInterest=Math.max(0,num(el('cashInterestRate').value));save();renderAll();showToast('Condições de recebimento atualizadas.');}

